using System;
public static class EconomyModelTests {
 static int checks;
 static void Check(bool b,string name){if(!b)throw new Exception(name);checks++;}
 static bool Near(double a,double b){return Math.Abs(a-b)<1e-7*Math.Max(1,Math.Abs(a));}
 static GodEconomyState State(){var s=new GodEconomyState();s.resources=100000;s.treasury.gold=100000;s.households.gold=10000;s.readingWork=100;return s;}
 public static void Main(){
 var w=new GodWallet();Check(GodEconomy.Issue(w,false,100),"issue gold");Check(GodEconomy.Issue(w,true,10),"issue god");Check(GodEconomy.SetRate(2),"rate");double eq=w.gold+w.god*2;Check(GodEconomy.Exchange(w,true,5)&&Near(eq,w.gold+w.god*2),"exchange conserved");Check(GodEconomy.Exchange(w,false,10)&&Near(eq,w.gold+w.god*2),"reverse conserved");double before=w.gold;Check(!GodEconomy.Exchange(w,false,1000)&&w.gold==before,"atomic insufficient");Check(!GodEconomy.Issue(w,false,double.NaN)&&!GodEconomy.SetRate(0),"invalid finite");Check(GodEconomy.Burn(w,true,1),"burn");
 var s=State();double total=GodEconomy.TotalGold(s),r=s.resources;for(int i=0;i<50;i++){s.nativeOutput+=100;s.practiceWork+=10;GodEconomy.Tick(s,100,10,false,50);}Check(Near(total,GodEconomy.TotalGold(s)),"annual conservation");Check(s.infrastructure>0&&s.knowledge>0&&s.resources<r&&s.era>0,"funded resources development");
 var empty=new GodEconomyState();empty.treasury.gold=1e12;GodEconomy.Tick(empty,100,0,false,0);Check(empty.infrastructure==0&&empty.lastOutput==0&&empty.era==0,"money not instant development");
 var noFunds=new GodEconomyState();noFunds.resources=1000;GodEconomy.Tick(noFunds,100,0,false,0);Check(noFunds.infrastructure==0,"construction requires funds");
 var war=State();double satisfaction=war.satisfaction;for(int i=0;i<12;i++)GodEconomy.Tick(war,100,92,true,100);Check(war.warLevel>=4&&war.satisfaction<satisfaction&&war.military.gold>0,"war escalation political cost");GodEconomy.Tick(war,100,0,false,0);Check(war.warLevel==0&&war.warYears==0,"peace reset");
 var overflow=new GodWallet();overflow.gold=double.MaxValue;Check(!GodEconomy.Issue(overflow,false,double.MaxValue)&&overflow.gold==double.MaxValue,"overflow atomic");
 var dual=new GodEconomyState();dual.resources=1000;dual.treasury.god=1000;GodEconomy.SetRate(2);double worth=GodEconomy.TotalGold(dual)+(dual.treasury.god+dual.households.god+dual.business.god)*2;GodEconomy.Tick(dual,100,10,true,20);Check(dual.lastBuildPaid==0&&dual.lastArmyPaid==0&&dual.treasury.god==1000,"god alone cannot settle production or military costs");Check(Near(worth,GodEconomy.TotalGold(dual)+(dual.treasury.god+dual.households.god+dual.business.god)*2),"dual-currency annual conservation");var shock=State();GodEconomy.SetRate(1);shock.nativeOutput=100;GodEconomy.Tick(shock,100,0,false,0);double price=shock.inflation;shock.treasury.god=1e6;shock.nativeOutput=100;GodEconomy.Tick(shock,100,0,false,0);Check(shock.inflation>price,"god issuance changes price pressure");price=shock.inflation;GodEconomy.SetRate(2);shock.nativeOutput=100;GodEconomy.Tick(shock,100,0,false,0);Check(shock.inflation>price,"rate revalues god in monetary pressure");
 var nativeOnly=new GodEconomyState();nativeOnly.business.gold=100;nativeOnly.households.gold=100;nativeOnly.resources=100;double trade=nativeOnly.business.gold,personal=nativeOnly.households.gold;GodEconomy.Tick(nativeOnly,10,0,false,0);Check(nativeOnly.business.gold==trade&&nativeOnly.households.gold==personal&&nativeOnly.treasury.gold==0,"no synthetic annual sales wages or tax");Check(nativeOnly.knowledge==0,"research requires actual completed reading");
 var reading=new GodEconomyState();reading.resources=100;reading.readingWork=3;GodEconomy.Tick(reading,10,0,false,0);Check(reading.knowledge>0&&reading.readingWork==0,"completed reading advances knowledge once");double learned=reading.knowledge;GodEconomy.Tick(reading,10,0,false,0);Check(reading.knowledge==learned,"idle year cannot repeat reading gain");
 var practice=new GodEconomyState();practice.resources=100;practice.practiceWork=10;GodEconomy.Tick(practice,10,0,false,0);Check(practice.knowledge>0&&practice.practiceWork==0,"real work enables pre-literate progress without passive research");
 var funded=new GodEconomyState();funded.treasury.gold=1000;GodEconomy.Tick(funded,10,2,false,0);double reservedEducation=funded.education.gold,reservedArmy=funded.military.gold;GodEconomy.Tick(funded,10,2,false,0);Check(funded.education.gold==reservedEducation&&funded.military.gold==reservedArmy,"unused education and military budgets are not reserved twice");
 var stagnant=new GodEconomyState{resources=1000};double raw=stagnant.resources;GodEconomy.Tick(stagnant,100,0,false,0);Check(stagnant.resources==raw&&stagnant.lastOutput==0,"no phantom output destroys raw materials");
 var output=new GodEconomyState{nativeOutput=21};GodEconomy.Tick(output,10,0,false,0);Check(output.lastOutput==21&&output.nativeOutput==0,"real accepted goods counted exactly once");GodEconomy.Tick(output,10,0,false,0);Check(output.lastOutput==0,"idle years do not repeat goods");
 var bankrupt=new GodEconomyState{infrastructure=100,monetized=1,wageArrears=100,foodCoverage=1,unemployment=1};for(int i=0;i<12;i++)GodEconomy.Tick(bankrupt,1000,0,false,0);Check(bankrupt.crisis>35&&bankrupt.stressYears>=3&&bankrupt.loyalty<100,"large unfunded state accumulates political crisis");Check(bankrupt.infrastructure<100,"unmaintained capital decays");
 double panic=bankrupt.crisis;bankrupt.treasury.gold=1000000;bankrupt.wageArrears=0;bankrupt.unemployment=0;for(int i=0;i<12;i++)GodEconomy.Tick(bankrupt,1000,0,false,0);Check(bankrupt.crisis<panic*.2,"restored funding recovers crisis rather than irreversible scripted collapse");
 double stress=0;for(int i=0;i<8;i++)stress=LifecyclePolicy.Stress(stress,0,0,0,0,1,true);Check(stress>80,"combined deprivation escalates promptly");double healed=stress;for(int i=0;i<8;i++)healed=LifecyclePolicy.Stress(healed,1,1,1,1,0,true);Check(healed<5,"crisis is recoverable");
 Check(LifecyclePolicy.Mobilize(10,8,true,true,1,0,0,1,0)==8,"small rebellion bypasses fifteen-adult floor");Check(LifecyclePolicy.Mobilize(100,98,true,true,1,0,0,1,0)==92,"rebel mobilization is ninety two percent of adults");
 Check(LifecyclePolicy.Mobilize(100,98,false,true,3,0,0,1,0)==0,"unfunded expansion is not free");Check(LifecyclePolicy.Mobilize(100,98,false,true,3,100000,0,1,0)>LifecyclePolicy.Mobilize(100,98,false,false,0,100000,0,1,0),"war mobilizes a larger funded share");
 Check(LifecyclePolicy.DeployThreshold(100,8,false)==8&&LifecyclePolicy.DeployThreshold(100,1,true)==1,"small armies no longer wait for seventy percent full");
 Check(LifecyclePolicy.HoldingCapacity(10,10,10,10,10)>LifecyclePolicy.HoldingCapacity(0,0,0,0,0),"skills increase personal god capacity");Check(LifecyclePolicy.Wage(6,2)>LifecyclePolicy.Wage(1,1),"military wages share era and price basis");
 var blocked=new GodEconomyState{infrastructure=100000,knowledge=100000,resources=100000,production=100,era=4};GodEconomy.Tick(blocked,10,0,false,0);Check(blocked.era==4,"industrial transition requires actual steam facilities");
 Console.WriteLine(checks+" economic checks passed");
 }
}
